// Проверены по README: JxButton, JxModal, JxDrawer, JxTabs, JxSelect, JxCombobox,
// JxCalendar, JxDateRangePicker + контракт value/onValueChange. Имена JxCard,
// JxSegmented, JxSlider, JxSwitch, JxDivider, JxBadge, JxStack выведены по
// соглашению пакета — сверь их с d.ts перед вмерживанием.
import { useState } from 'react';
import {
  JxBadge,
  JxCard,
  JxDivider,
  JxSegmented,
  JxSelect,
  JxSlider,
  JxStack,
  JxSwitch,
} from '@jinx-ui/react';

export type ThemeMode = 'light' | 'dark' | 'system';
export type FontFamily = 'system' | 'inter' | 'mono';

export type AppearanceSettings = {
  theme: ThemeMode;
  scale: number;
  dense: boolean;
  fontFamily: FontFamily;
};

type AppearanceSettingsScreenProps = {
  defaultValue?: AppearanceSettings;
  onChange?: (settings: AppearanceSettings) => void;
};

const DEFAULTS: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  dense: false,
  fontFamily: 'system',
};

const THEME_OPTIONS: { value: ThemeMode; label: string }[] = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const FONT_OPTIONS: { value: FontFamily; label: string }[] = [
  { value: 'system', label: 'Системный' },
  { value: 'inter', label: 'Inter' },
  { value: 'mono', label: 'Моноширинный' },
];

export default function AppearanceSettingsScreen({
  defaultValue = DEFAULTS,
  onChange,
}: AppearanceSettingsScreenProps) {
  const [settings, setSettings] = useState<AppearanceSettings>(defaultValue);

  const update = (patch: Partial<AppearanceSettings>) => {
    const next = { ...settings, ...patch };
    setSettings(next);
    onChange?.(next);
  };

  const themeLabel =
    THEME_OPTIONS.find((option) => option.value === settings.theme)?.label ?? '';

  return (
    <JxCard>
      <JxStack gap="var(--jx-space-6)">
        <JxStack
          direction="row"
          align="center"
          justify="space-between"
          gap="var(--jx-space-3)"
        >
          <h1 style={{ margin: 0, font: 'var(--jx-font-heading-lg)' }}>
            Внешний вид
          </h1>
          <JxBadge>{themeLabel}</JxBadge>
        </JxStack>

        <JxStack gap="var(--jx-space-2)">
          <label id="appearance-theme-label">Тема</label>
          <JxSegmented
            aria-labelledby="appearance-theme-label"
            options={THEME_OPTIONS}
            value={settings.theme}
            onValueChange={(theme: ThemeMode) => update({ theme })}
          />
        </JxStack>

        <JxStack gap="var(--jx-space-2)">
          <JxStack direction="row" align="center" justify="space-between">
            <label id="appearance-scale-label">Масштаб интерфейса</label>
            <span aria-live="polite">{settings.scale}%</span>
          </JxStack>
          <JxSlider
            aria-labelledby="appearance-scale-label"
            min={80}
            max={140}
            step={5}
            value={settings.scale}
            onValueChange={(scale: number) => update({ scale })}
          />
        </JxStack>

        <JxStack direction="row" align="center" justify="space-between" gap="var(--jx-space-4)">
          <label htmlFor="appearance-dense">Плотная вёрстка</label>
          <JxSwitch
            id="appearance-dense"
            checked={settings.dense}
            onCheckedChange={(dense: boolean) => update({ dense })}
          />
        </JxStack>

        <JxDivider />

        <JxStack gap="var(--jx-space-3)">
          <h2 style={{ margin: 0, font: 'var(--jx-font-heading-sm)' }}>Ещё</h2>
          <JxStack gap="var(--jx-space-2)">
            <label htmlFor="appearance-font">Шрифт</label>
            <JxSelect
              id="appearance-font"
              options={FONT_OPTIONS}
              value={settings.fontFamily}
              onValueChange={(fontFamily: FontFamily) => update({ fontFamily })}
            />
          </JxStack>
        </JxStack>
      </JxStack>
    </JxCard>
  );
}

